\set ON_ERROR_STOP on
BEGIN;
UPDATE channels SET models='gemini-3.8-flash-merge,gemini-flash,deepseek-flash,grok,gpt-luna,claude-sonnet,claude-opus',model_mapping='{"grok": "xai/grok-4.7", "gpt-luna": "openai/gpt-6-luna", "gemini-flash": "google/gemini-3.8-flash", "deepseek-flash": "deepseek/deepseek-v4.1-flash", "gemini-3.8-flash-merge": "google/gemini-3.8-flash", "claude-sonnet": "anthropic/claude-sonnet-5-5", "claude-opus": "anthropic/claude-opus-5-5"}',settings='{"disable_store": false, "advanced_custom": {"advanced_routes": [{"incoming_path": "/v1/messages", "upstream_path": "/v1/anthropic/v1/messages", "converter": "none", "models": ["claude-sonnet", "claude-opus"]}, {"converter": "none", "incoming_path": "/v1/chat/completions", "upstream_path": "/v1/chat/completions"}, {"converter": "none", "incoming_path": "/v1/responses", "upstream_path": "/v1/openai/responses"}, {"converter": "anthropic_messages_to_openai_chat_completions", "incoming_path": "/v1/messages", "upstream_path": "/v1/chat/completions"}, {"converter": "gemini_generate_content_to_openai_chat_completions", "incoming_path": "/v1beta/models/{model}:generateContent", "upstream_path": "/v1/chat/completions"}, {"converter": "none", "incoming_path": "/v1/models", "upstream_path": "/v1/models"}]}, "allow_service_tier": false, "allow_inference_geo": false, "allow_safety_identifier": false, "allow_include_obfuscation": false, "disable_task_polling_sleep": false, "upstream_model_update_check_enabled": false, "upstream_model_update_ignored_models": [], "upstream_model_update_last_check_time": 0, "upstream_model_update_auto_sync_enabled": false, "upstream_model_update_last_detected_models": []}' WHERE id=1 AND name='Merge wnlr2010';
UPDATE channels SET models='gemini-3.8-flash-merge-handimuse,gemini-flash,deepseek-flash,grok,gpt-luna,claude-sonnet,claude-opus',model_mapping='{"grok": "xai/grok-4.7", "gpt-luna": "openai/gpt-6-luna", "gemini-flash": "google/gemini-3.8-flash", "deepseek-flash": "deepseek/deepseek-v4.1-flash", "gemini-3.8-flash-merge-handimuse": "google/gemini-3.8-flash", "claude-sonnet": "anthropic/claude-sonnet-5-5", "claude-opus": "anthropic/claude-opus-5-5"}',settings='{"disable_store": false, "advanced_custom": {"advanced_routes": [{"incoming_path": "/v1/messages", "upstream_path": "/v1/anthropic/v1/messages", "converter": "none", "models": ["claude-sonnet", "claude-opus"]}, {"converter": "none", "incoming_path": "/v1/chat/completions", "upstream_path": "/v1/chat/completions"}, {"converter": "none", "incoming_path": "/v1/responses", "upstream_path": "/v1/openai/responses"}, {"converter": "anthropic_messages_to_openai_chat_completions", "incoming_path": "/v1/messages", "upstream_path": "/v1/chat/completions"}, {"converter": "gemini_generate_content_to_openai_chat_completions", "incoming_path": "/v1beta/models/{model}:generateContent", "upstream_path": "/v1/chat/completions"}, {"converter": "none", "incoming_path": "/v1/models", "upstream_path": "/v1/models"}]}, "allow_service_tier": false, "allow_inference_geo": false, "allow_safety_identifier": false, "allow_include_obfuscation": false, "disable_task_polling_sleep": false, "upstream_model_update_check_enabled": false, "upstream_model_update_ignored_models": [], "upstream_model_update_last_check_time": 0, "upstream_model_update_auto_sync_enabled": false, "upstream_model_update_last_detected_models": []}' WHERE id=5 AND name='Merge 2 - handimuse';
UPDATE channels SET models='gemini-3.8-flash-merge-handimuse,gemini-flash,deepseek-flash,grok,gpt-luna',model_mapping='{"grok": "xai/grok-4.7", "gpt-luna": "openai/gpt-6-luna", "gemini-flash": "google/gemini-3.8-flash", "deepseek-flash": "deepseek/deepseek-v4.1-flash", "gemini-3.8-flash-merge-handimuse": "google/gemini-3.8-flash", "claude-sonnet": "anthropic/claude-sonnet-5-5", "claude-opus": "anthropic/claude-opus-5-5"}',settings='{"disable_store": false, "advanced_custom": {"advanced_routes": [{"incoming_path": "/v1/messages", "upstream_path": "/v1/anthropic/v1/messages", "converter": "none", "models": ["claude-sonnet", "claude-opus"]}, {"converter": "none", "incoming_path": "/v1/chat/completions", "upstream_path": "/v1/chat/completions"}, {"converter": "none", "incoming_path": "/v1/responses", "upstream_path": "/v1/openai/responses"}, {"converter": "anthropic_messages_to_openai_chat_completions", "incoming_path": "/v1/messages", "upstream_path": "/v1/chat/completions"}, {"converter": "gemini_generate_content_to_openai_chat_completions", "incoming_path": "/v1beta/models/{model}:generateContent", "upstream_path": "/v1/chat/completions"}, {"converter": "none", "incoming_path": "/v1/models", "upstream_path": "/v1/models"}]}, "allow_service_tier": false, "allow_inference_geo": false, "allow_safety_identifier": false, "allow_include_obfuscation": false, "disable_task_polling_sleep": false, "upstream_model_update_check_enabled": false, "upstream_model_update_ignored_models": [], "upstream_model_update_last_check_time": 0, "upstream_model_update_auto_sync_enabled": false, "upstream_model_update_last_detected_models": []}' WHERE id=7 AND name='Merge 3 - raverevel';
INSERT INTO abilities ("group",model,channel_id,enabled,priority,weight,tag)
SELECT g,m,c.id,c.status=1,c.priority,c.weight,c.tag
FROM channels c CROSS JOIN unnest(string_to_array(c."group",',')) g CROSS JOIN unnest(ARRAY['claude-sonnet','claude-opus']) m
WHERE c.name ILIKE 'merge%' AND m=ANY(string_to_array(c.models,','))
ON CONFLICT ("group",model,channel_id) DO UPDATE SET enabled=EXCLUDED.enabled,priority=EXCLUDED.priority,weight=EXCLUDED.weight,tag=EXCLUDED.tag;
INSERT INTO options(key,value) VALUES('billing_setting.billing_mode','{"claude-sonnet": "tiered_expr", "claude-opus": "tiered_expr"}') ON CONFLICT(key) DO UPDATE SET value=(options.value::jsonb || EXCLUDED.value::jsonb)::text;
INSERT INTO options(key,value) VALUES('billing_setting.billing_expr','{"claude-sonnet": "tier(\"standard\", p * 2 + c * 10 + cr * 0.2 + cc * 2.5 + cc1h * 4)", "claude-opus": "tier(\"standard\", p * 4 + c * 20 + cr * 0.2 + cc * 5 + cc1h * 8)"}') ON CONFLICT(key) DO UPDATE SET value=(options.value::jsonb || EXCLUDED.value::jsonb)::text;
UPDATE abilities SET enabled=false WHERE channel_id=7 AND model IN ('claude-sonnet','claude-opus');
COMMIT;
